      if (event.key !== "Escape" || toggle.getAttribute("aria-expanded") !== "true") return;
      if (document.querySelector("dialog[open]")) return;
      setOpen(false);
      toggle.focus();
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    initMenu();
    NB.updatePlanCount();
    var year = document.getElementById("footer-year");
    if (year) year.textContent = String(new Date().getFullYear());
  });
})();

input.content:
/* Northbridge University course registration
   All text/background pairs below meet WCAG 2.2 AA contrast (4.5:1 for text, 3:1 for UI). */

:root {
  --ink: #1a1a2e;          /* 16.9:1 on white */
  --ink-muted: #4a4a5e;    /* 8.6:1 on white */
  --paper: #ffffff;
  --page: #f7f5fc;
  --purple: #4b1d8f;       /* white text 10.9:1 */
  --purple-dark: #2d1160;
  --magenta: #b4005a;      /* white text 6.8:1 */
  --magenta-dark: #8c0046;
  --teal: #00695c;         /* white text 6.5:1 */
  --blue: #1f4fbf;         /* white text 7.1:1 */
  --orange: #8a4b00;       /* white text 6.8:1 */
  --red: #a4161a;          /* white text 7.6:1 */
  --green: #1b5e20;        /* white text 7.9:1 */
  --yellow: #ffd23f;       /* on purple 7.8:1 */
  --border: #6b6b80;       /* 5.2:1 on white */
  --focus: #1a1a2e;
  --focus-on-dark: #ffd23f;
  --radius: 0.75rem;
  --shadow: 0 0.25rem 1rem rgba(45, 17, 96, 0.12);

  /* department colours, all with white text >= 4.5:1 */
  --dept-CSE: #1f4fbf;
  --dept-MATH: #6a1b9a;
  --dept-BIO: #00695c;
  --dept-ART: #b4005a;
  --dept-HIST: #8a4b00;
  --dept-PSY: #b3261e;
  --dept-MUS: #2e7d32;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

@media (min-width: 48rem) and (min-height: 30rem) {
  html {
    scroll-padding-top: 6.5rem; /* keeps focused elements clear of the sticky header */
  }
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--page);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1 0 auto;
}

img,
svg {
  max-width: 100%;
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0 0 0.5em;
}

h1 { font-size: 2rem; }
h2 { font-size: 1.5rem; }
h3 { font-size: 1.2rem; }

@media (min-width: 48rem) {
  h1 { font-size: 2.5rem; }
}

p {
  margin: 0 0 1em;
}

a {
  color: var(--blue);
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

a:hover {
  color: var(--purple);
  text-decoration-thickness: 0.15em;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.site-header :focus-visible,
.site-footer :focus-visible,
.hero :focus-visible,
.on-dark :focus-visible {
  outline-color: var(--focus-on-dark);
}

.container {
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1rem;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.icon {
  flex: none;
  width: 1.25em;
  height: 1.25em;
  vertical-align: -0.2em;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -10rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  background: var(--yellow);
  color: var(--ink);
  font-weight: 700;
  border-radius: 0 0 0.5rem 0.5rem;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- Header and navigation ---------- */
.site-header {
  background: linear-gradient(120deg, var(--purple-dark), var(--purple) 55%, #5b1f9e);
  color: #fff;
  border-bottom: 0.35rem solid var(--yellow);
}

@media (min-width: 48rem) and (min-height: 30rem) {
  .site-header {
    position: sticky;
    top: 0;
    z-index: 50;
  }
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  padding-top: 0.6rem;
  padding-bottom: 0.6rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: #fff;
  text-decoration: none;
  font-weight: 800;
  font-size: 1.1rem;
  line-height: 1.2;
  padding: 0.25rem 0;
}

.brand:hover {
  color: #fff;
  text-decoration: underline;
}

.brand-logo {
  width: 2.5rem;
  height: 2.5rem;
  flex: none;
}

.brand-sub {
  display: block;
  font-weight: 500;
  font-size: 0.85rem;
  color: #f1e9ff; /* 13:1 on purple */
}

.site-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.menu-toggle {
  display: none;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: var(--yellow);
  border: 2px solid var(--yellow);
  border-radius: 0.5rem;
  cursor: pointer;
}

.menu-toggle:hover {
  background: #fff;
}

.menu-toggle .icon-close { display: none; }
.menu-toggle[aria-expanded="true"] .icon-open { display: none; }
.menu-toggle[aria-expanded="true"] .icon-close { display: inline; }

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.9rem;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
}

.nav-list a:hover {
  border-color: #fff;
  color: #fff;
}

.nav-list a[aria-current="page"] {
  background: var(--yellow);
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 0.15em;
}

.nav-list a[aria-current="page"]:focus-visible {
  outline-color: #fff;
}

.nav-count {
  display: inline-block;
  min-width: 1.6rem;
  padding: 0 0.4rem;
  border-radius: 1rem;
  background: var(--magenta);
  color: #fff;
  font-size: 0.85rem;
  text-align: center;
  line-height: 1.6rem;
}

@media (max-width: 47.99rem) {
  .site-nav {
    width: 100%;
    align-items: stretch;
  }

  .js .menu-toggle {
    display: inline-flex;
    align-self: flex-start;
  }

  .header-inner {
    align-items: flex-start;
  }

  .nav-list {
    flex-direction: column;
    padding: 0.5rem 0;
  }

  .js .nav-list:not(.is-open) {
    display: none;
  }

  .nav-list a {
    display: flex;
  }
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 3rem;
  background: var(--ink);
  color: #fff;
  border-top: 0.35rem solid var(--magenta);
}

.footer-inner {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 2rem;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.25rem;
  padding-bottom: 1.25rem;
}

.footer-inner p {
  margin: 0;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer a {
  color: var(--yellow); /* 12.6:1 on ink */
  display: inline-block;
  padding: 0.25rem 0;
}

.site-footer a:hover {
  color: #fff;
}

/* ---------- Page header band ---------- */
.page-intro {
  padding: 2rem 0 1.5rem;
  background: linear-gradient(135deg, #fde7f3 0%, #ece6ff 50%, #e0f4f1 100%);
  border-bottom: 1px solid #d9cff0;
  margin-bottom: 2rem;
}

.page-intro p {
  max-width: 45rem;
  font-size: 1.1rem;
  color: var(--ink-muted);
}

.eyebrow {
  display: inline-block;
  margin-bottom: 0.5rem;
  padding: 0.15rem 0.75rem;
  border-radius: 1rem;
  background: var(--purple);
  color: #fff;
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

/* ---------- Hero (home) ---------- */
.hero {
  background:
    radial-gradient(circle at 85% 20%, rgba(255, 210, 63, 0.18) 0 18%, transparent 19%),
    linear-gradient(130deg, var(--purple-dark) 0%, var(--purple) 45%, var(--magenta) 100%);
  color: #fff;
  padding: 3rem 0;
  margin-bottom: 2.5rem;
}

.hero h1 {
  max-width: 40rem;
}

.hero p {
  max-width: 40rem;
  font-size: 1.15rem;
  color: #fff;
}

.hero a:not(.btn) {
  color: #fff;
}

.hero .highlight {
  color: var(--yellow);
}

.hero-search {
  margin: 1.5rem 0;
  max-width: 36rem;
}

.hero-search label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.55rem 1.1rem;
  font: inherit;
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
  cursor: pointer;
}

.btn-primary {
  background: var(--magenta);
  color: #fff;
  border-color: var(--magenta);
}

.btn-primary:hover {
  background: var(--magenta-dark);
  border-color: var(--magenta-dark);
  color: #fff;
}

.btn-secondary {
  background: #fff;
  color: var(--purple);
  border-color: var(--purple);
}

.btn-secondary:hover {
  background: #f1e9ff;
  color: var(--purple-dark);
}

.btn-teal {
  background: var(--teal);
  color: #fff;
  border-color: var(--teal);
}

.btn-teal:hover {
  background: #004d43;
  border-color: #004d43;
  color: #fff;
}

.btn-yellow {
  background: var(--yellow);
  color: var(--ink);
  border-color: var(--yellow);
}

.btn-yellow:hover {
  background: #fff;
  border-color: #fff;
  color: var(--ink);
}

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: #fff;
}

.btn-outline-light:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

.btn-danger {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-danger:hover {
  background: #7d1013;
  border-color: #7d1013;
  color: #fff;
}

.btn-small {
  min-height: 2.25rem;
  padding: 0.3rem 0.8rem;
  font-size: 0.95rem;
}

.btn[disabled] {
  background: #e4e2ea;
  border-color: #b9b6c4;
  color: #4a4a5e;
  cursor: not-allowed;
}

/* ---------- Forms ---------- */
.field {
  margin-bottom: 1.25rem;
}

.field label,
.field-label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.3rem;
}

.req {
  font-weight: 600;
  color: var(--magenta);
}

.hint {
  display: block;
  font-size: 0.95rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="search"],
select,
textarea {
  display: block;
  width: 100%;
  max-width: 32rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  color: var(--ink);
  background: #fff;
  border: 2px solid var(--border);
  border-radius: 0.5rem;
}

select {
  padding-right: 2rem;
}

input::placeholder {
  color: #5c5c70; /* 6.4:1 on white */
  opacity: 1;
}

input:hover,
select:hover,
textarea:hover {
  border-color: var(--purple);
}

input[aria-invalid="true"],
select[aria-invalid="true"] {
  border-color: var(--red);
  border-width: 3px;
}

input[type="checkbox"],
input[type="radio"] {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0.05rem 0 0;
  flex: none;
  accent-color: var(--purple);
}

fieldset {
  margin: 0 0 1.5rem;
  padding: 1rem 1.25rem 0.5rem;
  border: 2px solid #c9bfe3;
  border-radius: var(--radius);
  background: #fff;
  min-width: 0;
}

legend {
  padding: 0 0.5rem;
  font-weight: 800;
  font-size: 1.1rem;
}

.choice {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.choice label {
  font-weight: 500;
  cursor: pointer;
}

.choice-detail {
  display: block;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.field-error {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin: 0.4rem 0 0.75rem;
  color: var(--red);
  font-weight: 700;
}

.field-error[hidden] {
  display: none;
}

.error-summary {
  margin-bottom: 1.5rem;
  padding: 1rem 1.25rem;
  border: 3px solid var(--red);
  border-left-width: 0.75rem;
  border-radius: var(--radius);
  background: #fff5f5;
}

.error-summary-title {
  font-size: 1.25rem;
  color: var(--red);
}

.error-summary ul {
  margin: 0;
  padding-left: 1.25rem;
}

.error-summary a {
  color: var(--red);
  font-weight: 700;
}

.inline-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
}

.inline-row .field {
  flex: 1 1 14rem;
  margin-bottom: 0;
}

/* ---------- Search and filters ---------- */
.search-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.search-row input {
  flex: 1 1 12rem;
  max-width: none;
}

.filters-panel {
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.4rem solid var(--teal);
  box-shadow: var(--shadow);
}

.filters-panel h2 {
  font-size: 1.25rem;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.filter-grid .field {
  margin-bottom: 0;
}

.filter-grid select {
  max-width: none;
}

.filter-actions {
  margin-top: 1rem;
}

.results-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.results-count {
  margin: 0;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 0.5rem;
  background: #e0f4f1;
  color: #004d43;
}

/* ---------- Course cards ---------- */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.card-grid > li {
  display: flex;
}

.course-card {
  --dept-color: var(--purple);
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.5rem solid var(--dept-color);
  box-shadow: var(--shadow);
}

.dept-CSE { --dept-color: var(--dept-CSE); }
.dept-MATH { --dept-color: var(--dept-MATH); }
.dept-BIO { --dept-color: var(--dept-BIO); }
.dept-ART { --dept-color: var(--dept-ART); }
.dept-HIST { --dept-color: var(--dept-HIST); }
.dept-PSY { --dept-color: var(--dept-PSY); }
.dept-MUS { --dept-color: var(--dept-MUS); }

.card-top {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.75rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.1rem 0.6rem;
  border-radius: 1rem;
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1.6;
}

.badge-dept {
  background: var(--dept-color);
  color: #fff;
}

.badge-open {
  background: #e6f4ea;
  color: var(--green);
  border: 1px solid var(--green);
}

.badge-few {
  background: #fff4e5;
  color: var(--orange);
  border: 1px solid var(--orange);
}

.badge-full {
  background: #fde8ea;
  color: var(--red);
  border: 1px solid var(--red);
}

.badge-registered {
  background: var(--teal);
  color: #fff;
}

.badge-planned {
  background: var(--purple);
  color: #fff;
}

.course-title {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.course-code {
  display: block;
  font-size: 0.95rem;
  color: var(--dept-color);
  font-weight: 800;
  letter-spacing: 0.02em;
}

.course-desc {
  color: var(--ink-muted);
}

.course-meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 0.75rem;
  margin: 0 0 1rem;
  font-size: 0.95rem;
}

.course-meta dt {
  font-weight: 700;
}

.course-meta dd {
  margin: 0;
}

.card-action {
  margin-top: auto;
}

.card-action .btn {
  width: 100%;
}

.btn.is-added {
  background: #fff;
  color: var(--magenta);
  border-color: var(--magenta);
}

.btn.is-added:hover {
  background: #fde7f3;
}

.empty-state {
  padding: 2rem 1.25rem;
  text-align: center;
  background: #fff;
  border: 2px dashed #b3a6d6;
  border-radius: var(--radius);
}

/* ---------- Home ---------- */
.section {
  margin-bottom: 2.5rem;
}

.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: step;
}

.step {
  position: relative;
  padding: 1.25rem 1.25rem 1.25rem 4.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  counter-increment: step;
}

.step::before {
  content: counter(step);
  position: absolute;
  left: 1.25rem;
  top: 1.25rem;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  color: #fff;
  background: var(--step-color, var(--purple));
}

.step:nth-child(1) { --step-color: var(--magenta); border-bottom: 0.35rem solid var(--magenta); }
.step:nth-child(2) { --step-color: var(--teal); border-bottom: 0.35rem solid var(--teal); }
.step:nth-child(3) { --step-color: var(--blue); border-bottom: 0.35rem solid var(--blue); }

.step p {
  margin: 0;
}

.dept-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.dept-tile {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 6rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  background: var(--dept-color);
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 0.2em;
  font-weight: 800;
  font-size: 1.1rem;
}

.dept-tile:hover {
  color: #fff;
  text-decoration-thickness: 0.2em;
  filter: brightness(0.88);
}

.dept-tile span {
  font-weight: 500;
  font-size: 0.95rem;
  text-decoration: none;
  display: inline-block;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
}

.info-card {
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  border-left: 0.5rem solid var(--orange);
}

.info-card.teal { border-left-color: var(--teal); }

.dates-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.dates-list li {
  padding: 0.4rem 0;
  border-bottom: 1px solid #e3def0;
}

.dates-list li:last-child {
  border-bottom: 0;
}

.dates-list strong {
  display: inline-block;
  min-width: 7rem;
}

/* ---------- Registration page ---------- */
.layout-two {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 60rem) {
  .layout-two {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
    align-items: start;
  }
}

.panel {
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.panel-accent {
  border-top: 0.4rem solid var(--magenta);
}

.panel-teal {
  border-top: 0.4rem solid var(--teal);
}

.panel h2 {
  font-size: 1.25rem;
}

.success-panel {
  margin-bottom: 1.5rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #e6f4ea;
  border: 2px solid var(--green);
  border-left-width: 0.75rem;
}

.success-panel h2 {
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.summary-list {
  margin: 0 0 1rem;
  padding-left: 1.25rem;
}

.totals {
  font-weight: 700;
}

.add-course {
  margin-top: 0.5rem;
  padding-top: 1rem;
  border-top: 1px dashed #c9bfe3;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Profile ---------- */
.profile-card {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  align-items: center;
}

.avatar {
  display: grid;
  place-items: center;
  width: 5rem;
  height: 5rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--magenta), var(--purple));
  color: #fff;
  font-size: 1.75rem;
  font-weight: 800;
  flex: none;
}

.profile-details {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 1rem;
  margin: 0;
  overflow-wrap: anywhere;
}

.profile-details dt {
  font-weight: 700;
}

.profile-details dd {
  margin: 0;
}

.stat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
}

.stat {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-weight: 700;
  color: #fff;
}

.stat-1 { background: var(--purple); }
.stat-2 { background: var(--teal); }
.stat-3 { background: var(--magenta); }

/* ---------- Table ---------- */
.table-wrap {
  overflow-x: auto;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  background: #fff;
  margin-bottom: 1rem;
}

table {
  width: 100%;
  min-width: 46rem;
  border-collapse: collapse;
}

caption {
  text-align: left;
  font-weight: 800;
  font-size: 1.1rem;
  padding: 0.85rem 1rem;
  background: #ece6ff;
  color: var(--purple-dark);
}

th,
td {
  padding: 0.65rem 1rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid #e3def0;
}

thead th {
  background: var(--purple);
  color: #fff;
}

tbody th {
  white-space: nowrap;
}

tbody tr:nth-child(even) {
  background: #faf8ff;
}

tfoot th,
tfoot td {
  font-weight: 800;
  background: #fde7f3;
  border-bottom: 0;
}

.num {
  text-align: right;
}

.code-chip {
  display: inline-block;
  padding: 0 0.5rem;
  border-radius: 0.4rem;
  background: var(--dept-color);
  color: #fff;
}

/* ---------- Dialog ---------- */
dialog {
  width: min(32rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  overflow-y: auto;
  padding: 1.5rem;
  border: 0;
  border-top: 0.5rem solid var(--magenta);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  box-shadow: 0 1rem 3rem rgba(26, 26, 46, 0.35);
}

dialog::backdrop {
  background: rgba(26, 26, 46, 0.65);
}

dialog h2 {
  font-size: 1.4rem;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

/* ---------- Motion ---------- */
.btn,
.nav-list a,
.dept-tile,
input,
select {
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, filter 0.15s ease;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- Forced colours (Windows High Contrast) ---------- */
@media (forced-colors: active) {
  .btn,
  .badge,
  .nav-list a[aria-current="page"] {
    border: 2px solid ButtonText;
  }
}

toolu_018fvkf3Nmu7DS2ceDX7xxYh.content:
/* Northbridge University course registration
   All text/background pairs below meet WCAG 2.2 AA contrast (4.5:1 for text, 3:1 for UI). */

:root {
  --ink: #1a1a2e;          /* 16.9:1 on white */
  --ink-muted: #4a4a5e;    /* 8.6:1 on white */
  --paper: #ffffff;
  --page: #f7f5fc;
  --purple: #4b1d8f;       /* white text 10.9:1 */
  --purple-dark: #2d1160;
  --magenta: #b4005a;      /* white text 6.8:1 */
  --magenta-dark: #8c0046;
  --teal: #00695c;         /* white text 6.5:1 */
  --blue: #1f4fbf;         /* white text 7.1:1 */
  --orange: #8a4b00;       /* white text 6.8:1 */
  --red: #a4161a;          /* white text 7.6:1 */
  --green: #1b5e20;        /* white text 7.9:1 */
  --yellow: #ffd23f;       /* on purple 7.8:1 */
  --border: #6b6b80;       /* 5.2:1 on white */
  --focus: #1a1a2e;
  --focus-on-dark: #ffd23f;
  --radius: 0.75rem;
  --shadow: 0 0.25rem 1rem rgba(45, 17, 96, 0.12);

  /* department colours, all with white text >= 4.5:1 */
  --dept-CSE: #1f4fbf;
  --dept-MATH: #6a1b9a;
  --dept-BIO: #00695c;
  --dept-ART: #b4005a;
  --dept-HIST: #8a4b00;
  --dept-PSY: #b3261e;
  --dept-MUS: #2e7d32;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

@media (min-width: 48rem) and (min-height: 30rem) {
  html {
    scroll-padding-top: 6.5rem; /* keeps focused elements clear of the sticky header */
  }
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--page);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1 0 auto;
}

img,
svg {
  max-width: 100%;
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0 0 0.5em;
}

h1 { font-size: 2rem; }
h2 { font-size: 1.5rem; }
h3 { font-size: 1.2rem; }

@media (min-width: 48rem) {
  h1 { font-size: 2.5rem; }
}

p {
  margin: 0 0 1em;
}

a {
  color: var(--blue);
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

a:hover {
  color: var(--purple);
  text-decoration-thickness: 0.15em;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.site-header :focus-visible,
.site-footer :focus-visible,
.hero :focus-visible,
.on-dark :focus-visible {
  outline-color: var(--focus-on-dark);
}

.container {
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1rem;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.icon {
  flex: none;
  width: 1.25em;
  height: 1.25em;
  vertical-align: -0.2em;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -10rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  background: var(--yellow);
  color: var(--ink);
  font-weight: 700;
  border-radius: 0 0 0.5rem 0.5rem;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- Header and navigation ---------- */
.site-header {
  background: linear-gradient(120deg, var(--purple-dark), var(--purple) 55%, #5b1f9e);
  color: #fff;
  border-bottom: 0.35rem solid var(--yellow);
}

@media (min-width: 48rem) and (min-height: 30rem) {
  .site-header {
    position: sticky;
    top: 0;
    z-index: 50;
  }
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  padding-top: 0.6rem;
  padding-bottom: 0.6rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: #fff;
  text-decoration: none;
  font-weight: 800;
  font-size: 1.1rem;
  line-height: 1.2;
  padding: 0.25rem 0;
}

.brand:hover {
  color: #fff;
  text-decoration: underline;
}

.brand-logo {
  width: 2.5rem;
  height: 2.5rem;
  flex: none;
}

.brand-sub {
  display: block;
  font-weight: 500;
  font-size: 0.85rem;
  color: #f1e9ff; /* 13:1 on purple */
}

.site-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.menu-toggle {
  display: none;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: var(--yellow);
  border: 2px solid var(--yellow);
  border-radius: 0.5rem;
  cursor: pointer;
}

.menu-toggle:hover {
  background: #fff;
}

.menu-toggle .icon-close { display: none; }
.menu-toggle[aria-expanded="true"] .icon-open { display: none; }
.menu-toggle[aria-expanded="true"] .icon-close { display: inline; }

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.9rem;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
}

.nav-list a:hover {
  border-color: #fff;
  color: #fff;
}

.nav-list a[aria-current="page"] {
  background: var(--yellow);
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 0.15em;
}

.nav-list a[aria-current="page"]:focus-visible {
  outline-color: #fff;
}

.nav-count {
  display: inline-block;
  min-width: 1.6rem;
  padding: 0 0.4rem;
  border-radius: 1rem;
  background: var(--magenta);
  color: #fff;
  font-size: 0.85rem;
  text-align: center;
  line-height: 1.6rem;
}

@media (max-width: 47.99rem) {
  .site-nav {
    width: 100%;
    align-items: stretch;
  }

  .js .menu-toggle {
    display: inline-flex;
    align-self: flex-start;
  }

  .header-inner {
    align-items: flex-start;
  }

  .nav-list {
    flex-direction: column;
    padding: 0.5rem 0;
  }

  .js .nav-list:not(.is-open) {
    display: none;
  }

  .nav-list a {
    display: flex;
  }
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 3rem;
  background: var(--ink);
  color: #fff;
  border-top: 0.35rem solid var(--magenta);
}

.footer-inner {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 2rem;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.25rem;
  padding-bottom: 1.25rem;
}

.footer-inner p {
  margin: 0;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer a {
  color: var(--yellow); /* 12.6:1 on ink */
  display: inline-block;
  padding: 0.25rem 0;
}

.site-footer a:hover {
  color: #fff;
}

/* ---------- Page header band ---------- */
.page-intro {
  padding: 2rem 0 1.5rem;
  background: linear-gradient(135deg, #fde7f3 0%, #ece6ff 50%, #e0f4f1 100%);
  border-bottom: 1px solid #d9cff0;
  margin-bottom: 2rem;
}

.page-intro p {
  max-width: 45rem;
  font-size: 1.1rem;
  color: var(--ink-muted);
}

.eyebrow {
  display: inline-block;
  margin-bottom: 0.5rem;
  padding: 0.15rem 0.75rem;
  border-radius: 1rem;
  background: var(--purple);
  color: #fff;
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

/* ---------- Hero (home) ---------- */
.hero {
  background:
    radial-gradient(circle at 85% 20%, rgba(255, 210, 63, 0.18) 0 18%, transparent 19%),
    linear-gradient(130deg, var(--purple-dark) 0%, var(--purple) 45%, var(--magenta) 100%);
  color: #fff;
  padding: 3rem 0;
  margin-bottom: 2.5rem;
}

.hero h1 {
  max-width: 40rem;
}

.hero p {
  max-width: 40rem;
  font-size: 1.15rem;
  color: #fff;
}

.hero a:not(.btn) {
  color: #fff;
}

.hero .highlight {
  color: var(--yellow);
}

.hero-search {
  margin: 1.5rem 0;
  max-width: 36rem;
}

.hero-search label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.55rem 1.1rem;
  font: inherit;
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
  cursor: pointer;
}

.btn-primary {
  background: var(--magenta);
  color: #fff;
  border-color: var(--magenta);
}

.btn-primary:hover {
  background: var(--magenta-dark);
  border-color: var(--magenta-dark);
  color: #fff;
}

.btn-secondary {
  background: #fff;
  color: var(--purple);
  border-color: var(--purple);
}

.btn-secondary:hover {
  background: #f1e9ff;
  color: var(--purple-dark);
}

.btn-teal {
  background: var(--teal);
  color: #fff;
  border-color: var(--teal);
}

.btn-teal:hover {
  background: #004d43;
  border-color: #004d43;
  color: #fff;
}

.btn-yellow {
  background: var(--yellow);
  color: var(--ink);
  border-color: var(--yellow);
}

.btn-yellow:hover {
  background: #fff;
  border-color: #fff;
  color: var(--ink);
}

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: #fff;
}

.btn-outline-light:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

.btn-danger {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-danger:hover {
  background: #7d1013;
  border-color: #7d1013;
  color: #fff;
}

.btn-small {
  min-height: 2.25rem;
  padding: 0.3rem 0.8rem;
  font-size: 0.95rem;
}

.btn[disabled] {
  background: #e4e2ea;
  border-color: #b9b6c4;
  color: #4a4a5e;
  cursor: not-allowed;
}

/* ---------- Forms ---------- */
.field {
  margin-bottom: 1.25rem;
}

.field label,
.field-label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.3rem;
}

.req {
  font-weight: 600;
  color: var(--magenta);
}

.hint {
  display: block;
  font-size: 0.95rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="search"],
select,
textarea {
  display: block;
  width: 100%;
  max-width: 32rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  color: var(--ink);
  background: #fff;
  border: 2px solid var(--border);
  border-radius: 0.5rem;
}

select {
  padding-right: 2rem;
}

input::placeholder {
  color: #5c5c70; /* 6.4:1 on white */
  opacity: 1;
}

input:hover,
select:hover,
textarea:hover {
  border-color: var(--purple);
}

input[aria-invalid="true"],
select[aria-invalid="true"] {
  border-color: var(--red);
  border-width: 3px;
}

input[type="checkbox"],
input[type="radio"] {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0.05rem 0 0;
  flex: none;
  accent-color: var(--purple);
}

fieldset {
  margin: 0 0 1.5rem;
  padding: 1rem 1.25rem 0.5rem;
  border: 2px solid #c9bfe3;
  border-radius: var(--radius);
  background: #fff;
  min-width: 0;
}

legend {
  padding: 0 0.5rem;
  font-weight: 800;
  font-size: 1.1rem;
}

.choice {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.choice label {
  font-weight: 500;
  cursor: pointer;
}

.choice-detail {
  display: block;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.field-error {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin: 0.4rem 0 0.75rem;
  color: var(--red);
  font-weight: 700;
}

.field-error[hidden] {
  display: none;
}

.error-summary {
  margin-bottom: 1.5rem;
  padding: 1rem 1.25rem;
  border: 3px solid var(--red);
  border-left-width: 0.75rem;
  border-radius: var(--radius);
  background: #fff5f5;
}

.error-summary-title {
  font-size: 1.25rem;
  color: var(--red);
}

.error-summary ul {
  margin: 0;
  padding-left: 1.25rem;
}

.error-summary a {
  color: var(--red);
  font-weight: 700;
}

.inline-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
}

.inline-row .field {
  flex: 1 1 14rem;
  margin-bottom: 0;
}

/* ---------- Search and filters ---------- */
.search-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.search-row input {
  flex: 1 1 12rem;
  max-width: none;
}

.filters-panel {
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.4rem solid var(--teal);
  box-shadow: var(--shadow);
}

.filters-panel h2 {
  font-size: 1.25rem;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.filter-grid .field {
  margin-bottom: 0;
}

.filter-grid select {
  max-width: none;
}

.filter-actions {
  margin-top: 1rem;
}

.results-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.results-count {
  margin: 0;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 0.5rem;
  background: #e0f4f1;
  color: #004d43;
}

/* ---------- Course cards ---------- */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.card-grid > li {
  display: flex;
}

.course-card {
  --dept-color: var(--purple);
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.5rem solid var(--dept-color);
  box-shadow: var(--shadow);
}

.dept-CSE { --dept-color: var(--dept-CSE); }
.dept-MATH { --dept-color: var(--dept-MATH); }
.dept-BIO { --dept-color: var(--dept-BIO); }
.dept-ART { --dept-color: var(--dept-ART); }
.dept-HIST { --dept-color: var(--dept-HIST); }
.dept-PSY { --dept-color: var(--dept-PSY); }
.dept-MUS { --dept-color: var(--dept-MUS); }

.card-top {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.75rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.1rem 0.6rem;
  border-radius: 1rem;
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1.6;
}

.badge-dept {
  background: var(--dept-color);
  color: #fff;
}

.badge-open {
  background: #e6f4ea;
  color: var(--green);
  border: 1px solid var(--green);
}

.badge-few {
  background: #fff4e5;
  color: var(--orange);
  border: 1px solid var(--orange);
}

.badge-full {
  background: #fde8ea;
  color: var(--red);
  border: 1px solid var(--red);
}

.badge-registered {
  background: var(--teal);
  color: #fff;
}

.badge-planned {
  background: var(--purple);
  color: #fff;
}

.course-title {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.course-code {
  display: block;
  font-size: 0.95rem;
  color: var(--dept-color);
  font-weight: 800;
  letter-spacing: 0.02em;
}

.course-desc {
  color: var(--ink-muted);
}

.course-meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 0.75rem;
  margin: 0 0 1rem;
  font-size: 0.95rem;
}

.course-meta dt {
  font-weight: 700;
}

.course-meta dd {
  margin: 0;
}

.card-action {
  margin-top: auto;
}

.card-action .btn {
  width: 100%;
}

.btn.is-added {
  background: #fff;
  color: var(--magenta);
  border-color: var(--magenta);
}

.btn.is-added:hover {
  background: #fde7f3;
}

.empty-state {
  padding: 2rem 1.25rem;
  text-align: center;
  background: #fff;
  border: 2px dashed #b3a6d6;
  border-radius: var(--radius);
}

/* ---------- Home ---------- */
.section {
  margin-bottom: 2.5rem;
}

.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: step;
}

.step {
  position: relative;
  padding: 1.25rem 1.25rem 1.25rem 4.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  counter-increment: step;
}

.step::before {
  content: counter(step);
  position: absolute;
  left: 1.25rem;
  top: 1.25rem;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  color: #fff;
  background: var(--step-color, var(--purple));
}

.step:nth-child(1) { --step-color: var(--magenta); border-bottom: 0.35rem solid var(--magenta); }
.step:nth-child(2) { --step-color: var(--teal); border-bottom: 0.35rem solid var(--teal); }
.step:nth-child(3) { --step-color: var(--blue); border-bottom: 0.35rem solid var(--blue); }

.step p {
  margin: 0;
}

.dept-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.dept-tile {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 6rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  background: var(--dept-color);
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 0.2em;
  font-weight: 800;
  font-size: 1.1rem;
}

.dept-tile:hover {
  color: #fff;
  text-decoration-thickness: 0.2em;
  filter: brightness(0.88);
}

.dept-tile span {
  font-weight: 500;
  font-size: 0.95rem;
  text-decoration: none;
  display: inline-block;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
}

.info-card {
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  border-left: 0.5rem solid var(--orange);
}

.info-card.teal { border-left-color: var(--teal); }

.dates-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.dates-list li {
  padding: 0.4rem 0;
  border-bottom: 1px solid #e3def0;
}

.dates-list li:last-child {
  border-bottom: 0;
}

.dates-list strong {
  display: inline-block;
  min-width: 7rem;
}

/* ---------- Registration page ---------- */
.layout-two {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 60rem) {
  .layout-two {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
    align-items: start;
  }
}

.panel {
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.panel-accent {
  border-top: 0.4rem solid var(--magenta);
}

.panel-teal {
  border-top: 0.4rem solid var(--teal);
}

.panel h2 {
  font-size: 1.25rem;
}

.success-panel {
  margin-bottom: 1.5rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #e6f4ea;
  border: 2px solid var(--green);
  border-left-width: 0.75rem;
}

.success-panel h2 {
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.summary-list {
  margin: 0 0 1rem;
  padding-left: 1.25rem;
}

.totals {
  font-weight: 700;
}

.add-course {
  margin-top: 0.5rem;
  padding-top: 1rem;
  border-top: 1px dashed #c9bfe3;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Profile ---------- */
.profile-card {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  align-items: center;
}

.avatar {
  display: grid;
  place-items: center;
  width: 5rem;
  height: 5rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--magenta), var(--purple));
  color: #fff;
  font-size: 1.75rem;
  font-weight: 800;
  flex: none;
}

.profile-details {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 1rem;
  margin: 0;
  overflow-wrap: anywhere;
}

.profile-details dt {
  font-weight: 700;
}

.profile-details dd {
  margin: 0;
}

.stat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
}

.stat {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-weight: 700;
  color: #fff;
}

.stat-1 { background: var(--purple); }
.stat-2 { background: var(--teal); }
.stat-3 { background: var(--magenta); }

/* ---------- Table ---------- */
.table-wrap {
  overflow-x: auto;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  background: #fff;
  margin-bottom: 1rem;
}

table {
  width: 100%;
  min-width: 46rem;
  border-collapse: collapse;
}

caption {
  text-align: left;
  font-weight: 800;
  font-size: 1.1rem;
  padding: 0.85rem 1rem;
  background: #ece6ff;
  color: var(--purple-dark);
}

th,
td {
  padding: 0.65rem 1rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid #e3def0;
}

thead th {
  background: var(--purple);
  color: #fff;
}

tbody th {
  white-space: nowrap;
}

tbody tr:nth-child(even) {
  background: #faf8ff;
}

tfoot th,
tfoot td {
  font-weight: 800;
  background: #fde7f3;
  border-bottom: 0;
}

.num {
  text-align: right;
}

.code-chip {
  display: inline-block;
  padding: 0 0.5rem;
  border-radius: 0.4rem;
  background: var(--dept-color);
  color: #fff;
}

/* ---------- Dialog ---------- */
dialog {
  width: min(32rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  overflow-y: auto;
  padding: 1.5rem;
  border: 0;
  border-top: 0.5rem solid var(--magenta);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  box-shadow: 0 1rem 3rem rgba(26, 26, 46, 0.35);
}

dialog::backdrop {
  background: rgba(26, 26, 46, 0.65);
}

dialog h2 {
  font-size: 1.4rem;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

/* ---------- Motion ---------- */
.btn,
.nav-list a,
.dept-tile,
input,
select {
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, filter 0.15s ease;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- Forced colours (Windows High Contrast) ---------- */
@media (forced-colors: active) {
  .btn,
  .badge,
  .nav-list a[aria-current="page"] {
    border: 2px solid ButtonText;
  }
}

tool_use_result.content:
/* Northbridge University course registration
   All text/background pairs below meet WCAG 2.2 AA contrast (4.5:1 for text, 3:1 for UI). */

:root {
  --ink: #1a1a2e;          /* 16.9:1 on white */
  --ink-muted: #4a4a5e;    /* 8.6:1 on white */
  --paper: #ffffff;
  --page: #f7f5fc;
  --purple: #4b1d8f;       /* white text 10.9:1 */
  --purple-dark: #2d1160;
  --magenta: #b4005a;      /* white text 6.8:1 */
  --magenta-dark: #8c0046;
  --teal: #00695c;         /* white text 6.5:1 */
  --blue: #1f4fbf;         /* white text 7.1:1 */
  --orange: #8a4b00;       /* white text 6.8:1 */
  --red: #a4161a;          /* white text 7.6:1 */
  --green: #1b5e20;        /* white text 7.9:1 */
  --yellow: #ffd23f;       /* on purple 7.8:1 */
  --border: #6b6b80;       /* 5.2:1 on white */
  --focus: #1a1a2e;
  --focus-on-dark: #ffd23f;
  --radius: 0.75rem;
  --shadow: 0 0.25rem 1rem rgba(45, 17, 96, 0.12);

  /* department colours, all with white text >= 4.5:1 */
  --dept-CSE: #1f4fbf;
  --dept-MATH: #6a1b9a;
  --dept-BIO: #00695c;
  --dept-ART: #b4005a;
  --dept-HIST: #8a4b00;
  --dept-PSY: #b3261e;
  --dept-MUS: #2e7d32;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

@media (min-width: 48rem) and (min-height: 30rem) {
  html {
    scroll-padding-top: 6.5rem; /* keeps focused elements clear of the sticky header */
  }
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--page);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1 0 auto;
}

img,
svg {
  max-width: 100%;
}

h1,
h2,
h3 {
  line-height: 1.25;
  margin: 0 0 0.5em;
}

h1 { font-size: 2rem; }
h2 { font-size: 1.5rem; }
h3 { font-size: 1.2rem; }

@media (min-width: 48rem) {
  h1 { font-size: 2.5rem; }
}

p {
  margin: 0 0 1em;
}

a {
  color: var(--blue);
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

a:hover {
  color: var(--purple);
  text-decoration-thickness: 0.15em;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.site-header :focus-visible,
.site-footer :focus-visible,
.hero :focus-visible,
.on-dark :focus-visible {
  outline-color: var(--focus-on-dark);
}

.container {
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
  padding: 0 1rem;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.icon {
  flex: none;
  width: 1.25em;
  height: 1.25em;
  vertical-align: -0.2em;
}

/* ---------- Skip link ---------- */
.skip-link {
  position: absolute;
  left: 1rem;
  top: -10rem;
  z-index: 100;
  padding: 0.75rem 1rem;
  background: var(--yellow);
  color: var(--ink);
  font-weight: 700;
  border-radius: 0 0 0.5rem 0.5rem;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- Header and navigation ---------- */
.site-header {
  background: linear-gradient(120deg, var(--purple-dark), var(--purple) 55%, #5b1f9e);
  color: #fff;
  border-bottom: 0.35rem solid var(--yellow);
}

@media (min-width: 48rem) and (min-height: 30rem) {
  .site-header {
    position: sticky;
    top: 0;
    z-index: 50;
  }
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  padding-top: 0.6rem;
  padding-bottom: 0.6rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: #fff;
  text-decoration: none;
  font-weight: 800;
  font-size: 1.1rem;
  line-height: 1.2;
  padding: 0.25rem 0;
}

.brand:hover {
  color: #fff;
  text-decoration: underline;
}

.brand-logo {
  width: 2.5rem;
  height: 2.5rem;
  flex: none;
}

.brand-sub {
  display: block;
  font-weight: 500;
  font-size: 0.85rem;
  color: #f1e9ff; /* 13:1 on purple */
}

.site-nav {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.menu-toggle {
  display: none;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: var(--yellow);
  border: 2px solid var(--yellow);
  border-radius: 0.5rem;
  cursor: pointer;
}

.menu-toggle:hover {
  background: #fff;
}

.menu-toggle .icon-close { display: none; }
.menu-toggle[aria-expanded="true"] .icon-open { display: none; }
.menu-toggle[aria-expanded="true"] .icon-close { display: inline; }

.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.9rem;
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
}

.nav-list a:hover {
  border-color: #fff;
  color: #fff;
}

.nav-list a[aria-current="page"] {
  background: var(--yellow);
  color: var(--ink);
  text-decoration: underline;
  text-decoration-thickness: 0.15em;
}

.nav-list a[aria-current="page"]:focus-visible {
  outline-color: #fff;
}

.nav-count {
  display: inline-block;
  min-width: 1.6rem;
  padding: 0 0.4rem;
  border-radius: 1rem;
  background: var(--magenta);
  color: #fff;
  font-size: 0.85rem;
  text-align: center;
  line-height: 1.6rem;
}

@media (max-width: 47.99rem) {
  .site-nav {
    width: 100%;
    align-items: stretch;
  }

  .js .menu-toggle {
    display: inline-flex;
    align-self: flex-start;
  }

  .header-inner {
    align-items: flex-start;
  }

  .nav-list {
    flex-direction: column;
    padding: 0.5rem 0;
  }

  .js .nav-list:not(.is-open) {
    display: none;
  }

  .nav-list a {
    display: flex;
  }
}

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 3rem;
  background: var(--ink);
  color: #fff;
  border-top: 0.35rem solid var(--magenta);
}

.footer-inner {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 2rem;
  align-items: center;
  justify-content: space-between;
  padding-top: 1.25rem;
  padding-bottom: 1.25rem;
}

.footer-inner p {
  margin: 0;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer a {
  color: var(--yellow); /* 12.6:1 on ink */
  display: inline-block;
  padding: 0.25rem 0;
}

.site-footer a:hover {
  color: #fff;
}

/* ---------- Page header band ---------- */
.page-intro {
  padding: 2rem 0 1.5rem;
  background: linear-gradient(135deg, #fde7f3 0%, #ece6ff 50%, #e0f4f1 100%);
  border-bottom: 1px solid #d9cff0;
  margin-bottom: 2rem;
}

.page-intro p {
  max-width: 45rem;
  font-size: 1.1rem;
  color: var(--ink-muted);
}

.eyebrow {
  display: inline-block;
  margin-bottom: 0.5rem;
  padding: 0.15rem 0.75rem;
  border-radius: 1rem;
  background: var(--purple);
  color: #fff;
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

/* ---------- Hero (home) ---------- */
.hero {
  background:
    radial-gradient(circle at 85% 20%, rgba(255, 210, 63, 0.18) 0 18%, transparent 19%),
    linear-gradient(130deg, var(--purple-dark) 0%, var(--purple) 45%, var(--magenta) 100%);
  color: #fff;
  padding: 3rem 0;
  margin-bottom: 2.5rem;
}

.hero h1 {
  max-width: 40rem;
}

.hero p {
  max-width: 40rem;
  font-size: 1.15rem;
  color: #fff;
}

.hero a:not(.btn) {
  color: #fff;
}

.hero .highlight {
  color: var(--yellow);
}

.hero-search {
  margin: 1.5rem 0;
  max-width: 36rem;
}

.hero-search label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.55rem 1.1rem;
  font: inherit;
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  border-radius: 0.5rem;
  border: 2px solid transparent;
  cursor: pointer;
}

.btn-primary {
  background: var(--magenta);
  color: #fff;
  border-color: var(--magenta);
}

.btn-primary:hover {
  background: var(--magenta-dark);
  border-color: var(--magenta-dark);
  color: #fff;
}

.btn-secondary {
  background: #fff;
  color: var(--purple);
  border-color: var(--purple);
}

.btn-secondary:hover {
  background: #f1e9ff;
  color: var(--purple-dark);
}

.btn-teal {
  background: var(--teal);
  color: #fff;
  border-color: var(--teal);
}

.btn-teal:hover {
  background: #004d43;
  border-color: #004d43;
  color: #fff;
}

.btn-yellow {
  background: var(--yellow);
  color: var(--ink);
  border-color: var(--yellow);
}

.btn-yellow:hover {
  background: #fff;
  border-color: #fff;
  color: var(--ink);
}

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: #fff;
}

.btn-outline-light:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

.btn-danger {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}

.btn-danger:hover {
  background: #7d1013;
  border-color: #7d1013;
  color: #fff;
}

.btn-small {
  min-height: 2.25rem;
  padding: 0.3rem 0.8rem;
  font-size: 0.95rem;
}

.btn[disabled] {
  background: #e4e2ea;
  border-color: #b9b6c4;
  color: #4a4a5e;
  cursor: not-allowed;
}

/* ---------- Forms ---------- */
.field {
  margin-bottom: 1.25rem;
}

.field label,
.field-label {
  display: block;
  font-weight: 700;
  margin-bottom: 0.3rem;
}

.req {
  font-weight: 600;
  color: var(--magenta);
}

.hint {
  display: block;
  font-size: 0.95rem;
  color: var(--ink-muted);
  margin-bottom: 0.35rem;
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="search"],
select,
textarea {
  display: block;
  width: 100%;
  max-width: 32rem;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  font: inherit;
  color: var(--ink);
  background: #fff;
  border: 2px solid var(--border);
  border-radius: 0.5rem;
}

select {
  padding-right: 2rem;
}

input::placeholder {
  color: #5c5c70; /* 6.4:1 on white */
  opacity: 1;
}

input:hover,
select:hover,
textarea:hover {
  border-color: var(--purple);
}

input[aria-invalid="true"],
select[aria-invalid="true"] {
  border-color: var(--red);
  border-width: 3px;
}

input[type="checkbox"],
input[type="radio"] {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0.05rem 0 0;
  flex: none;
  accent-color: var(--purple);
}

fieldset {
  margin: 0 0 1.5rem;
  padding: 1rem 1.25rem 0.5rem;
  border: 2px solid #c9bfe3;
  border-radius: var(--radius);
  background: #fff;
  min-width: 0;
}

legend {
  padding: 0 0.5rem;
  font-weight: 800;
  font-size: 1.1rem;
}

.choice {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.choice label {
  font-weight: 500;
  cursor: pointer;
}

.choice-detail {
  display: block;
  color: var(--ink-muted);
  font-size: 0.95rem;
}

.field-error {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  margin: 0.4rem 0 0.75rem;
  color: var(--red);
  font-weight: 700;
}

.field-error[hidden] {
  display: none;
}

.error-summary {
  margin-bottom: 1.5rem;
  padding: 1rem 1.25rem;
  border: 3px solid var(--red);
  border-left-width: 0.75rem;
  border-radius: var(--radius);
  background: #fff5f5;
}

.error-summary-title {
  font-size: 1.25rem;
  color: var(--red);
}

.error-summary ul {
  margin: 0;
  padding-left: 1.25rem;
}

.error-summary a {
  color: var(--red);
  font-weight: 700;
}

.inline-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem;
}

.inline-row .field {
  flex: 1 1 14rem;
  margin-bottom: 0;
}

/* ---------- Search and filters ---------- */
.search-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.search-row input {
  flex: 1 1 12rem;
  max-width: none;
}

.filters-panel {
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.4rem solid var(--teal);
  box-shadow: var(--shadow);
}

.filters-panel h2 {
  font-size: 1.25rem;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.filter-grid .field {
  margin-bottom: 0;
}

.filter-grid select {
  max-width: none;
}

.filter-actions {
  margin-top: 1rem;
}

.results-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.results-count {
  margin: 0;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 0.5rem;
  background: #e0f4f1;
  color: #004d43;
}

/* ---------- Course cards ---------- */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 19rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.card-grid > li {
  display: flex;
}

.course-card {
  --dept-color: var(--purple);
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  border-top: 0.5rem solid var(--dept-color);
  box-shadow: var(--shadow);
}

.dept-CSE { --dept-color: var(--dept-CSE); }
.dept-MATH { --dept-color: var(--dept-MATH); }
.dept-BIO { --dept-color: var(--dept-BIO); }
.dept-ART { --dept-color: var(--dept-ART); }
.dept-HIST { --dept-color: var(--dept-HIST); }
.dept-PSY { --dept-color: var(--dept-PSY); }
.dept-MUS { --dept-color: var(--dept-MUS); }

.card-top {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.75rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.1rem 0.6rem;
  border-radius: 1rem;
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1.6;
}

.badge-dept {
  background: var(--dept-color);
  color: #fff;
}

.badge-open {
  background: #e6f4ea;
  color: var(--green);
  border: 1px solid var(--green);
}

.badge-few {
  background: #fff4e5;
  color: var(--orange);
  border: 1px solid var(--orange);
}

.badge-full {
  background: #fde8ea;
  color: var(--red);
  border: 1px solid var(--red);
}

.badge-registered {
  background: var(--teal);
  color: #fff;
}

.badge-planned {
  background: var(--purple);
  color: #fff;
}

.course-title {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
}

.course-code {
  display: block;
  font-size: 0.95rem;
  color: var(--dept-color);
  font-weight: 800;
  letter-spacing: 0.02em;
}

.course-desc {
  color: var(--ink-muted);
}

.course-meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.15rem 0.75rem;
  margin: 0 0 1rem;
  font-size: 0.95rem;
}

.course-meta dt {
  font-weight: 700;
}

.course-meta dd {
  margin: 0;
}

.card-action {
  margin-top: auto;
}

.card-action .btn {
  width: 100%;
}

.btn.is-added {
  background: #fff;
  color: var(--magenta);
  border-color: var(--magenta);
}

.btn.is-added:hover {
  background: #fde7f3;
}

.empty-state {
  padding: 2rem 1.25rem;
  text-align: center;
  background: #fff;
  border: 2px dashed #b3a6d6;
  border-radius: var(--radius);
}

/* ---------- Home ---------- */
.section {
  margin-bottom: 2.5rem;
}

.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: step;
}

.step {
  position: relative;
  padding: 1.25rem 1.25rem 1.25rem 4.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  counter-increment: step;
}

.step::before {
  content: counter(step);
  position: absolute;
  left: 1.25rem;
  top: 1.25rem;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  color: #fff;
  background: var(--step-color, var(--purple));
}

.step:nth-child(1) { --step-color: var(--magenta); border-bottom: 0.35rem solid var(--magenta); }
.step:nth-child(2) { --step-color: var(--teal); border-bottom: 0.35rem solid var(--teal); }
.step:nth-child(3) { --step-color: var(--blue); border-bottom: 0.35rem solid var(--blue); }

.step p {
  margin: 0;
}

.dept-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr));
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.dept-tile {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 6rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  background: var(--dept-color);
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 0.2em;
  font-weight: 800;
  font-size: 1.1rem;
}

.dept-tile:hover {
  color: #fff;
  text-decoration-thickness: 0.2em;
  filter: brightness(0.88);
}

.dept-tile span {
  font-weight: 500;
  font-size: 0.95rem;
  text-decoration: none;
  display: inline-block;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
}

.info-card {
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: var(--shadow);
  border-left: 0.5rem solid var(--orange);
}

.info-card.teal { border-left-color: var(--teal); }

.dates-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.dates-list li {
  padding: 0.4rem 0;
  border-bottom: 1px solid #e3def0;
}

.dates-list li:last-child {
  border-bottom: 0;
}

.dates-list strong {
  display: inline-block;
  min-width: 7rem;
}

/* ---------- Registration page ---------- */
.layout-two {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 60rem) {
  .layout-two {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
    align-items: start;
  }
}

.panel {
  padding: 1.25rem;
  background: #fff;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.panel-accent {
  border-top: 0.4rem solid var(--magenta);
}

.panel-teal {
  border-top: 0.4rem solid var(--teal);
}

.panel h2 {
  font-size: 1.25rem;
}

.success-panel {
  margin-bottom: 1.5rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  background: #e6f4ea;
  border: 2px solid var(--green);
  border-left-width: 0.75rem;
}

.success-panel h2 {
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.summary-list {
  margin: 0 0 1rem;
  padding-left: 1.25rem;
}

.totals {
  font-weight: 700;
}

.add-course {
  margin-top: 0.5rem;
  padding-top: 1rem;
  border-top: 1px dashed #c9bfe3;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ---------- Profile ---------- */
.profile-card {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  align-items: center;
}

.avatar {
  display: grid;
  place-items: center;
  width: 5rem;
  height: 5rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--magenta), var(--purple));
  color: #fff;
  font-size: 1.75rem;
  font-weight: 800;
  flex: none;
}

.profile-details {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 1rem;
  margin: 0;
  overflow-wrap: anywhere;
}

.profile-details dt {
  font-weight: 700;
}

.profile-details dd {
  margin: 0;
}

.stat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
}

.stat {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-weight: 700;
  color: #fff;
}

.stat-1 { background: var(--purple); }
.stat-2 { background: var(--teal); }
.stat-3 { background: var(--magenta); }

/* ---------- Table ---------- */
.table-wrap {
  overflow-x: auto;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  background: #fff;
  margin-bottom: 1rem;
}

table {
  width: 100%;
  min-width: 46rem;
  border-collapse: collapse;
}

caption {
  text-align: left;
  font-weight: 800;
  font-size: 1.1rem;
  padding: 0.85rem 1rem;
  background: #ece6ff;
  color: var(--purple-dark);
}

th,
td {
  padding: 0.65rem 1rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid #e3def0;
}

thead th {
  background: var(--purple);
  color: #fff;
}

tbody th {
  white-space: nowrap;
}

tbody tr:nth-child(even) {
  background: #faf8ff;
}

tfoot th,
tfoot td {
  font-weight: 800;
  background: #fde7f3;
  border-bottom: 0;
}

.num {
  text-align: right;
}

.code-chip {
  display: inline-block;
  padding: 0 0.5rem;
  border-radius: 0.4rem;
  background: var(--dept-color);
  color: #fff;
}

/* ---------- Dialog ---------- */
dialog {
  width: min(32rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  overflow-y: auto;
  padding: 1.5rem;
  border: 0;
  border-top: 0.5rem solid var(--magenta);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  box-shadow: 0 1rem 3rem rgba(26, 26, 46, 0.35);
}

dialog::backdrop {
  background: rgba(26, 26, 46, 0.65);
}

dialog h2 {
  font-size: 1.4rem;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1.25rem;
}

/* ---------- Motion ---------- */
.btn,
.nav-list a,
.dept-tile,
input,
select {
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, filter 0.15s ease;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- Forced colours (Windows High Contrast) ---------- */
@media (forced-colors: active) {
  .btn,
  .badge,
  .nav-list a[aria-current="page"] {
    border: 2px solid ButtonText;
  }
}

input.content:
/* Course catalog: search, filters and course cards. */
(function () {
  "use strict";

  var NB = window.NB;

  document.addEventListener("DOMContentLoaded", function () {
    var form = document.getElementById("search-form");
    var q = document.getElementById("q");
    var dept = document.getElementById("filter-dept");
    var level = document.getElementById("filter-level");
    var credits = document.getElementById("filter-credits");
    var availability = document.getElementById("filter-availability");
    var list = document.getElementById("course-list");
    var empty = document.getElementById("empty-state");
    var count = document.getElementById("results-count");
    var clearBtn = document.getElementById("clear-filters");

    NB.departments.forEach(function (d) {
      dept.add(new Option(d.name, d.id));
    });
    NB.levels.forEach(function (l) {
      level.add(new Option(l.name, l.id));
    });

    /* Prefill from the URL, for example catalog.html?q=bio or ?dept=CSE from the home page. */
    var params = new URLSearchParams(window.location.search);
    q.value = params.get("q") || "";
    [[dept, "dept"], [level, "level"], [credits, "credits"], [availability, "availability"]].forEach(function (pair) {
      var value = params.get(pair[1]);
      if (value && Array.prototype.some.call(pair[0].options, function (o) { return o.value === value; })) {
        pair[0].value = value;
      }
    });

    function matches(course) {
      var term = q.value.trim().toLowerCase();
      if (term) {
        var haystack = [course.code, course.code.replace(" ", ""), course.title, course.instructor,
          course.description, NB.deptName(course.dept)].join(" ").toLowerCase();
        var words = term.split(/\s+/);
        if (!words.every(function (w) { return haystack.indexOf(w) !== -1; })) return false;
      }
      if (dept.value && course.dept !== dept.value) return false;
      if (level.value && course.level !== level.value) return false;
      if (credits.value === "1-2" && course.credits > 2) return false;
      if (credits.value === "3" && course.credits !== 3) return false;
      if (credits.value === "4" && course.credits !== 4) return false;
      if (availability.value === "available" && NB.seatsLeft(course) === 0) return false;
      if (availability.value === "full" && NB.seatsLeft(course) > 0) return false;
      return true;
    }

    function actionHtml(course) {
      var name = course.code + " " + course.title;
      if (NB.isRegistered(course.id)) {
        return '<a class="btn btn-teal" href="profile.html" aria-label="View on profile: ' + NB.escape(name) + ', registered">View on profile</a>';
      }
      if (NB.seatsLeft(course) === 0 && !NB.isPlanned(course.id)) {
        return '<button type="button" class="btn" disabled aria-label="Course full: ' + NB.escape(name) + '">Course full</button>';
      }
      return planButtonHtml(course);
    }

    function planButtonHtml(course) {
      var planned = NB.isPlanned(course.id);
      var name = course.code + " " + course.title;
      return '<button type="button" class="btn ' + (planned ? "btn-primary is-added" : "btn-primary") + '" data-course="' + course.id + '"' +
        ' aria-label="' + (planned ? "Remove from plan: " : "Add to plan: ") + NB.escape(name) + '">' +
        (planned ? "Remove from plan" : "Add to plan") + "</button>";
    }

    function statusBadges(course) {
      var a = NB.availability(course);
      var icons = {
        open: '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="m5 12.5 4.5 4.5L19 7.5" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>',
        few: '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="M12 4 2.5 20h19z" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><path d="M12 10v4.5M12 17.2v.3" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>',
        full: '<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2.5"/><path d="M6 18 18 6" stroke="currentColor" stroke-width="2.5"/></svg>'
      };
      var html = '<span class="badge badge-dept">' + NB.escape(NB.deptName(course.dept)) + "</span>" +
        '<span class="badge badge-' + a.key + '">' + icons[a.key] + NB.escape(a.detail) + "</span>";
      if (NB.isRegistered(course.id)) {
        html += '<span class="badge badge-registered">Registered</span>';
      } else if (NB.isPlanned(course.id)) {
        html += '<span class="badge badge-planned" data-planned-badge>In your plan</span>';
      }
      return html;
    }

    function cardHtml(course) {
      var titleId = "course-" + course.id + "-title";
      return '<li><article class="course-card dept-' + course.dept + '" aria-labelledby="' + titleId + '">' +
        '<div class="card-top" data-badges>' + statusBadges(course) + "</div>" +
        '<h3 class="course-title" id="' + titleId + '"><span class="course-code">' + NB.escape(course.code) + "</span> " + NB.escape(course.title) + "</h3>" +
        '<p class="course-desc">' + NB.escape(course.description) + "</p>" +
        '<dl class="course-meta">' +
        "<dt>Instructor</dt><dd>" + NB.escape(course.instructor) + "</dd>" +
        "<dt>Schedule</dt><dd>" + NB.escape(NB.scheduleText(course)) + "</dd>" +
        "<dt>Room</dt><dd>" + NB.escape(course.room) + "</dd>" +
        "<dt>Credits</dt><dd>" + course.credits + "</dd>" +
        "</dl>" +
        '<div class="card-action">' + actionHtml(course) + "</div>" +
        "</article></li>";
    }

    function render() {
      var results = NB.courses.filter(matches);
      list.innerHTML = results.map(cardHtml).join("");
      empty.hidden = results.length > 0;
      var filtered = q.value.trim() || dept.value || level.value || credits.value || availability.value;
      var text;
      if (results.length === 0) text = "No courses found";
      else if (!filtered) text = "Showing all " + NB.coursesText(results.length);
      else text = NB.coursesText(results.length) + " found";
      if (count.textContent !== text) count.textContent = text;
    }

    function syncUrl() {
      var next = new URLSearchParams();
      if (q.value.trim()) next.set("q", q.value.trim());
      if (dept.value) next.set("dept", dept.value);
      if (level.value) next.set("level", level.value);
      if (credits.value) next.set("credits", credits.value);
      if (availability.value) next.set("availability", availability.value);
      var query = next.toString();
      try {
        window.history.replaceState(null, "", query ? "?" + query : window.location.pathname);
      } catch (e) {
        /* file:// in some browsers does not allow this; ignore */
      }
    }

    function update() {
      render();
      syncUrl();
    }

    var typingTimer = null;
    q.addEventListener("input", function () {
      window.clearTimeout(typingTimer);
      typingTimer = window.setTimeout(update, 400);
    });
    [dept, level, credits, availability].forEach(function (select) {
      select.addEventListener("change", update);
    });
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      window.clearTimeout(typingTimer);
      update();
    });
    clearBtn.addEventListener("click", function () {
      form.reset();
      q.value = "";
      update();
      NB.announce("Search and filters cleared.");
    });

    /* Add or remove a course from the plan, updating the card in place so focus stays on the button. */
    list.addEventListener("click", function (event) {
      var button = event.target.closest("button[data-course]");
      if (!button) return;
      var course = NB.findCourse(button.getAttribute("data-course"));
      if (!course) return;
      var plan = NB.getPlan();
      var index = plan.indexOf(course.id);
