const { chromium } = require('playwright');
const fs = require('fs');
const axe = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
(async () => {
  const browser = await chromium.launch();
  const errors = [];
  async function newPage(width=1280) {
    const ctx = await browser.newContext({ viewport: { width, height: 800 } });
    const page = await ctx.newPage();
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    page.on('pageerror', e => errors.push(e.message));
    return page;
  }
  async function runAxe(page, label) {
    await page.addScriptTag({ content: axe });
    const r = await page.evaluate(async () => await axe.run(document, { runOnly: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }));
    for (const v of r.violations) console.log(label, 'AXE', v.id, v.impact, v.nodes.length, v.nodes.slice(0,3).map(n=>n.target.join(' ')).join(' | '));
  }
  const pages = ['index.html','catalog.html','register.html','profile.html'];
  for (const w of [1280, 320]) {
    for (const p of pages) {
      const page = await newPage(w);
      await page.goto('http://localhost:8765/' + p);
      await page.waitForTimeout(200);
      await runAxe(page, `${w} ${p}`);
      const sw = await page.evaluate(() => document.documentElement.scrollWidth);
      if (sw > w) console.log(w, p, 'HORIZONTAL OVERFLOW', sw);
      await page.context().close();
    }
  }
  // Flow: catalog search + add
  const page = await newPage(1280);
  await page.goto('http://localhost:8765/catalog.html?dept=CSE');
  console.log('count', await page.textContent('#results-count'));
  await page.fill('#q', 'data');
  await page.waitForTimeout(600);
  console.log('count', await page.textContent('#results-count'));
  await page.click('button[data-course="CSE216"]');
  await page.waitForTimeout(100);
  console.log('btn', await page.getAttribute('button[data-course="CSE216"]', 'aria-label'), await page.textContent('#announcer'));
  await page.click('#clear-filters');
  await page.click('button[data-course="BIO110"]'); // conflicts with CSE216
  await page.goto('http://localhost:8765/register.html');
  console.log('choices', await page.$$eval('input[name=courses]', e => e.map(x=>x.value)));
  await page.click('#review-btn');
  console.log('focus', await page.evaluate(() => document.activeElement.id), await page.textContent('#error-summary'));
  await page.uncheck('#course-BIO110');
  await page.check('#reg-ack');
  await page.click('#review-btn');
  console.log('dialog open', await page.evaluate(() => document.getElementById('confirm-dialog').open), 'focus', await page.evaluate(() => document.activeElement.id));
  await runAxe(page, 'dialog');
  await page.keyboard.press('Escape');
  console.log('after esc focus', await page.evaluate(() => document.activeElement.id));
  await page.click('#review-btn');
  await page.click('#confirm-ok');
  console.log('after confirm focus', await page.evaluate(() => document.activeElement.id), (await page.textContent('#success-body')).trim().slice(0,80));
  await page.goto('http://localhost:8765/profile.html');
  console.log('rows', await page.$$eval('#registered-body tr', r => r.length));
  await page.click('button[data-drop="MATH221"]');
  console.log('drop focus', await page.evaluate(() => document.activeElement.id));
  await page.click('#drop-ok');
  console.log('after drop focus', await page.evaluate(() => document.activeElement.getAttribute('aria-label')), await page.textContent('#announcer'));
  await page.fill('#p-phone', 'abc');
  await page.click('text=Save details');
  console.log('profile err focus', await page.evaluate(() => document.activeElement.id));
  await page.fill('#p-phone', '555-123-4567');
  await page.click('text=Save details');
  await page.waitForTimeout(100);
  console.log('saved', await page.textContent('#profile-status'));
  // Mobile menu
  const m = await newPage(375);
  await m.goto('http://localhost:8765/index.html');
  console.log('menu visible', await m.isVisible('#primary-menu'));
  await m.focus('.menu-toggle'); await m.keyboard.press('Enter');
  console.log('menu open', await m.isVisible('#primary-menu'), await m.getAttribute('.menu-toggle','aria-expanded'));
  await m.keyboard.press('Tab'); await m.keyboard.press('Escape');
  console.log('menu after esc', await m.isVisible('#primary-menu'), await m.evaluate(() => document.activeElement.className));
  await m.keyboard.press('Space');
  console.log('space open', await m.getAttribute('.menu-toggle','aria-expanded'));
  console.log('ERRORS', errors);
  await browser.close();
})();
EOF
