const { JSDOM, VirtualConsole } = require('jsdom');
const errors = [];
async function load(path) {
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push(path + ': ' + e.message));
  vc.on('error', e => errors.push(path + ': ' + e));
  const dom = await JSDOM.fromURL('http://localhost:8765/' + path, { runScripts: 'dangerously', resources: 'usable', pretendToBeVisual: true, virtualConsole: vc,
    beforeParse(w) {
      w.HTMLDialogElement.prototype.showModal = function () { this.open = true; };
      w.HTMLDialogElement.prototype.close = function (v) { if (v !== undefined) this.returnValue = v; this.open = false; this.dispatchEvent(new w.Event('close')); };
      w.HTMLElement.prototype.scrollIntoView = function () {};
    } });
  await new Promise(r => dom.window.addEventListener('load', r));
  await new Promise(r => setTimeout(r, 100));
  return dom.window;
}
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  let w = await load('index.html');
  // headings check helper
  const heads = w => [...w.document.querySelectorAll('h1,h2,h3')].map(h => h.tagName).join(',');
  console.log('home', heads(w));
  w = await load('catalog.html?dept=CSE');
  console.log('catalog', w.document.querySelectorAll('#course-list li').length, w.document.getElementById('results-count').textContent);
  const q = w.document.getElementById('q'); q.value = 'data'; q.dispatchEvent(new w.Event('input', {bubbles:true}));
  await sleep(500);
  console.log('search', w.document.getElementById('results-count').textContent);
  w.document.querySelector('button[data-course="CSE216"]').click();
  await sleep(100);
  console.log('add', w.document.querySelector('button[data-course="CSE216"]').getAttribute('aria-label'), '|', w.document.getElementById('announcer').textContent, '| nav', w.document.querySelector('[data-plan-count]').textContent);
  w.document.getElementById('clear-filters').click();
  w.document.querySelector('button[data-course="BIO110"]').click();
  console.log('ids unique', (() => { const ids=[...w.document.querySelectorAll('[id]')].map(e=>e.id); return ids.length === new Set(ids).size; })());
  w.localStorage && null;
  // persist to next page: jsdom localStorage per origin is per-window; carry over manually
  const plan = w.localStorage.getItem('nb-plan');
  w = await load('register.html');
  w.localStorage.setItem('nb-plan', plan);
  w = await load('register.html');
  const d = w.document;
  console.log('choices', [...d.querySelectorAll('input[name=courses]')].map(x=>x.value), 'name', d.getElementById('reg-name').value);
  d.getElementById('reg-id').value = '12';
  d.getElementById('review-btn').click();
  console.log('focus', d.activeElement.id, '|', d.getElementById('error-summary').textContent);
  console.log('id described', d.getElementById('reg-id').getAttribute('aria-describedby'), d.getElementById('reg-id').getAttribute('aria-invalid'));
  d.getElementById('reg-id').value = '20231234';
  d.getElementById('course-BIO110').click();
  d.getElementById('reg-ack').click();
  d.getElementById('review-btn').click();
  console.log('dialog', d.getElementById('confirm-dialog').open, d.activeElement.id, d.getElementById('confirm-totals').textContent);
  d.getElementById('confirm-cancel').click();
  console.log('cancel focus', d.activeElement.id);
  d.getElementById('review-btn').click();
  d.getElementById('confirm-ok').click();
  console.log('confirm focus', d.activeElement.id, d.title, '| choices now', [...d.querySelectorAll('input[name=courses]')].map(x=>x.value));
  const reg = w.localStorage.getItem('nb-registered');
  w = await load('profile.html');
  let p = w.document;
  console.log('rows', p.querySelectorAll('#registered-body tr').length, p.getElementById('total-credits').textContent);
  p.querySelector('button[data-drop="MATH221"]').click();
  console.log('drop dialog', p.getElementById('drop-dialog').open, p.activeElement.id, p.getElementById('drop-title').textContent);
  p.getElementById('drop-ok').click();
  await sleep(100);
  console.log('after drop', p.activeElement.getAttribute('aria-label'), '|', p.getElementById('announcer').textContent);
  for (const b of [...p.querySelectorAll('button[data-drop]')]) { b.click(); p.getElementById('drop-ok').click(); }
  console.log('all dropped focus', p.activeElement.id, p.getElementById('registered-empty').hidden);
  p.getElementById('p-phone').value = 'abc';
  p.querySelector('#profile-form button[type=submit]').click();
  console.log('profile err', p.activeElement.id, p.getElementById('p-phone-error').textContent);
  p.getElementById('p-phone').value = '555-123-4567';
  p.querySelector('#profile-form button[type=submit]').click();
  await sleep(100);
  console.log('saved', p.getElementById('profile-status').textContent, p.getElementById('p-phone').getAttribute('aria-describedby'));
  // menu
  const mt = p.querySelector('.menu-toggle'); mt.click();
  console.log('menu', mt.getAttribute('aria-expanded'), p.getElementById('primary-menu').className);
  p.dispatchEvent(new w.KeyboardEvent('keydown', {key:'Escape', bubbles:true}));
  console.log('menu esc', mt.getAttribute('aria-expanded'), p.activeElement === mt);
  console.log('ERRORS', errors);
  process.exit(0);
})();
EOF
