  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push(path + ': ' + e.message));
  vc.on('error', e => errors.push(path + ': ' + e));
  const dom = await JSDOM.fromURL('http://localhost:8765/' + path, { runScripts: 'dangerously', resources: 'usable', pretendToBeVisual: true, virtualConsole: vc,
